bool AudioStreamGeneratorPlayback::push_buffer(const PackedVector2Array &frames) {
	int to_write = frames.size();
	if (buffer.space_left() < to_write) {
		return false;
	}

	const Vector2 *r = frames.ptr();
	if constexpr (sizeof(real_t) == 4) {
		//write directly
		buffer.write((const AudioFrame *)r, to_write);
	} else {
		//convert from double
		AudioFrame buf[2048];
		int ofs = 0;
		while (to_write) {
			int w = MIN(to_write, 2048);
			for (int i = 0; i < w; i++) {
				buf[i] = AudioFrame(r[i + ofs]);
			}
			buffer.write(buf, w);
			ofs += w;
			to_write -= w;
		}
	}
	return true;
}
